34	/// Prompt the user for a recovery action after a step failure.
35	///
36	/// Returns the chosen action. The `fix` parameter controls whether a Fix
37	/// option appears in the menu. The `has_hint` flag indicates a low-confidence
38	/// match exists, which adds a "Fix (custom)" option for the user to enter
39	/// their own command. The `fix_history` set tracks which fix commands have
40	/// already been attempted — if the suggested fix was already tried, it is
41	/// not offered again.
42	pub fn prompt_recovery(
43	    ui: &mut (impl Prompter + OutputWriter + ?Sized),
44	    step_name: &str,
45	    fix: Option<&FixSuggestion>,
46	    has_hint: bool,
47	    fix_history: &HashSet<String>,
48	    step_indent: usize,
49	) -> Result<RecoveryAction> {
50	    let pad = " ".repeat(step_indent);
51	    let mut options = vec![PromptOption {
52	        label: "Retry".to_string(),
53	        value: "retry".to_string(),
54	    }];
55	
56	    if let Some(f) = fix {
57	        if fix_history.contains(&f.command) {
58	            ui.warning(&format!(
59	                "{}Previous fix `{}` did not resolve this error.",
60	                pad, f.command
61	            ));
62	        } else {
63	            options.push(PromptOption {
64	                label: format!("Fix — {}", f.label),
65	                value: "fix".to_string(),
66	            });
67	        }
68	    }
69	
70	    if has_hint {
71	        options.push(PromptOption {
72	            label: "Fix (custom) — enter your own command".to_string(),
73	            value: "custom_fix".to_string(),
74	        });
75	    }
76	
77	    options.push(PromptOption {
78	        label: "Skip".to_string(),
79	        value: "skip".to_string(),
80	    });
81	
82	    options.push(PromptOption {
83	        label: "Shell".to_string(),
84	        value: "shell".to_string(),
85	    });
86	
87	    options.push(PromptOption {
88	        label: "Abort".to_string(),
89	        value: "abort".to_string(),
90	    });
91	
92	    let prompt = Prompt {
93	        key: format!("recovery_{}", step_name),
94	        question: "How do you want to proceed?".to_string(),
95	        prompt_type: PromptType::Select { options },
96	        default: Some("retry".to_string()),
97	    };
98	
99	    let answer = ui.prompt(&prompt)?;
100	    let value = answer.as_string();
101	
102	    match value.as_str() {
103	        "retry" => Ok(RecoveryAction::Retry),
104	        "fix" => {
105	            if let Some(f) = fix {
106	                Ok(RecoveryAction::Fix(f.command.clone()))
107	            } else {
108	                Ok(RecoveryAction::Retry)
109	            }
110	        }
111	        "custom_fix" => {
112	            let input_prompt = Prompt {
113	                key: format!("custom_fix_{}", step_name),
114	                question: "Enter fix command:".to_string(),
115	                prompt_type: PromptType::Input,
116	                default: None,
117	            };
118	            let input = ui.prompt(&input_prompt)?;
119	            let cmd = input.as_string();
120	            if cmd.trim().is_empty() {
121	                // User entered nothing, treat as retry
122	                Ok(RecoveryAction::Retry)
123	            } else {
124	                Ok(RecoveryAction::CustomFix(cmd))
125	            }
126	        }
127	        "skip" => Ok(RecoveryAction::Skip),
128	        "shell" => Ok(RecoveryAction::Shell),
129	        "abort" => Ok(RecoveryAction::Abort),
130	        _ => Ok(RecoveryAction::Retry),
131	    }
132	}
