1	//! Step-level execution manager.
2	//!
3	//! Owns step state and handles step execution, prompts, error blocks,
4	//! and step-level UI output. Extracted from `orchestrate.rs` to separate
5	//! step-level concerns from workflow-level orchestration.
6	
7	use std::collections::{HashMap, HashSet};
8	use std::path::Path;
9	
10	use crate::checks::evaluator::CheckEvaluator;
11	use crate::checks::CheckResult;
12	use crate::config::interpolation::InterpolationContext;
13	use crate::config::schema::StepOverride;
14	use crate::error::{BivvyError, Result};
15	use crate::logging::{BehaviorFlags, BivvyEvent, DecisionTrace, EventBus, StepOutcomeKind};
16	use crate::requirements::checker::GapChecker;
17	use crate::requirements::installer;
18	use crate::snapshots::SnapshotStore;
19	use crate::state::satisfaction::SatisfactionCache;
20	use crate::state::StateStore;
21	use crate::steps::{ResolvedStep, StepResult, StepStatus};
22	use crate::ui::theme::BivvyTheme;
23	use crate::ui::{Prompt, PromptOption, PromptType, StatusKind, UserInterface};
24	
25	use super::decision::{BlockReason, SkipReason, StepDecision};
26	use super::diagnostic;
27	use super::display::StepDisplay;
28	use super::engine::{self, EngineContext, EvaluationResult};
29	use super::execution::{config_prompt_to_ui_prompt, execute_step_with_recovery};
30	use super::patterns::StepContext;
31	use super::satisfaction;
32	
33	/// Options passed from the workflow layer to control step execution.
34	pub(super) struct StepExecutionOptions<'a> {
35	    pub dry_run: bool,
36	    pub interactive: bool,
37	    pub diagnostic_funnel: bool,
38	    pub project_root: &'a Path,
39	    /// YAML-defined env (settings + workflow), pre-merged in priority order.
40	    /// Step-level env layers and `process_env` are applied on top.
41	    pub base_env: &'a HashMap<String, String>,
42	    /// Parent process environment. Wins over `base_env` and step env.
43	    pub process_env: &'a HashMap<String, String>,
44	    pub force_steps: &'a HashSet<String>,
45	    pub force_all: bool,
46	    pub provided_requirements: &'a HashSet<String>,
47	}
48	
49	impl StepExecutionOptions<'_> {
50	    /// Whether the named step should be forced (workflow-wide or by name).
51	    pub(super) fn should_force(&self, step_name: &str) -> bool {
52	        self.force_all || self.force_steps.contains(step_name)
53	    }
54	}
55	
56	/// Why a step was skipped at runtime.
57	///
58	/// This lets the workflow layer categorize skips without inspecting
59	/// `StepResult` internals — per-step classification stays in StepManager.
60	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
61	pub(super) enum SkipCategory {
62	    /// Check passed — step is already satisfied.
63	    Satisfied,
64	    /// Dependency was skipped by user, so this step was transitively skipped.
65	    DependencySkipped,
66	    /// User actively declined a prompt (autorun, confirm, sensitive).
67	    UserDeclined,
68	    /// User chose to skip during recovery after a failure.
69	    /// Unlike `UserDeclined`, this does NOT block dependents — the user
70	    /// explicitly chose to continue past the failure.
71	    RecoverySkipped,
72	    /// Other skip reason (generic fallback from engine).
73	    Other,
74	}
75	
76	/// The action taken by a step during execution, returned to the workflow layer.
77	pub(super) enum StepAction {
78	    /// Step executed successfully.
79	    Completed(StepResult),
80	    /// Step was skipped at runtime, with the reason categorized.
81	    Skipped(StepResult, SkipCategory),
82	    /// Step failed.
83	    Failed(StepResult),
84	    /// Step was blocked (dependency failed, precondition failed, etc.).
85	    Blocked,
86	    /// User chose to abort the workflow.
87	    Aborted(StepResult),
88	}
89	
90	/// Manages the execution of a single step within a workflow.
91	///
92	/// Handles step-level concerns: printing step headers, evaluating checks,
93	/// showing prompts, executing the step command, and handling recovery.
94	/// Does NOT know about workflow state, progress bars, or summaries.
95	pub(super) struct StepManager<'a> {
96	    step: &'a ResolvedStep,
97	    step_name: &'a str,
98	    index: usize,
99	    total: usize,
100	    theme: &'a BivvyTheme,
101	}
102	
103	impl<'a> StepManager<'a> {
104	    /// Create a new StepManager for a specific step.
105	    pub fn new(
106	        step: &'a ResolvedStep,
107	        step_name: &'a str,
108	        index: usize,
109	        total: usize,
110	        theme: &'a BivvyTheme,
111	    ) -> Self {
112	        Self {
113	            step,
114	            step_name,
115	            index,
116	            total,
117	            theme,
118	        }
119	    }
120	
121	    /// Format the step number string, e.g., `[1/7]`.
122	    fn step_number(&self) -> String {
123	        format!("[{}/{}]", self.index + 1, self.total)
124	    }
125	
126	    /// Compute the indentation width that aligns content under the step name.
127	    fn step_indent(&self) -> usize {
128	        self.step_number().len() + 1 // +1 for the space after
129	    }
130	
131	    /// Compute the indentation padding string.
132	    fn step_pad(&self) -> String {
133	        " ".repeat(self.step_indent())
134	    }
135	
136	    /// Format the step display line with optional title.
137	    fn step_header_text(&self) -> String {
138	        let step_number = self.step_number();
139	        let step_header = format!(
140	            "{} {}",
141	            self.theme.step_number.apply_to(&step_number),
142	            self.theme.step_title.apply_to(self.step_name)
143	        );
144	        if self.step_name == self.step.title {
145	            step_header
146	        } else {
147	            format!(
148	                "{} {} {}",
149	                step_header,
150	                self.theme.dim.apply_to("—"),
151	                self.theme.dim.apply_to(&self.step.title)
152	            )
153	        }
154	    }
155	
156	    /// Execute the step through the full decision/execution lifecycle.
157	    ///
158	    /// This method handles:
159	    /// - Requirement gap resolution
160	    /// - Decision engine evaluation
161	    /// - Prompts (rerun, autorun, confirm, sensitive)
162	    /// - Step-level template prompts
163	    /// - Step execution with retry and recovery
164	    /// - Event emission for all step-level events
165	    ///
166	    /// Returns a `StepAction` describing what happened.
167	    #[allow(clippy::too_many_arguments)]
168	    pub fn execute(
169	        &self,
170	        opts: &StepExecutionOptions<'_>,
171	        context: &mut InterpolationContext,
172	        step_overrides: &HashMap<String, StepOverride>,
173	        gap_checker: &mut Option<&mut GapChecker<'_>>,
174	        snapshot_store: &mut SnapshotStore,
175	        steps: &HashMap<String, ResolvedStep>,
176	        state: Option<&StateStore>,
177	        satisfaction_cache: &mut SatisfactionCache,
178	        failed_steps: &HashSet<String>,
179	        user_skipped_steps: &HashSet<String>,
180	        satisfied_steps: &HashSet<String>,
181	        named_check_results: &mut HashMap<String, CheckResult>,
182	        results: &[StepResult],
183	        ui: &mut dyn UserInterface,
184	        step_display: &mut dyn StepDisplay,
185	        event_bus: &mut EventBus,
186	    ) -> Result<StepAction> {
187	        let step_pad = self.step_pad();
188	        let step_header = self.step_header_text();
189	
190	        // Emit step planned
191	        event_bus.emit(&BivvyEvent::StepPlanned {
192	            name: self.step_name.to_string(),
193	            index: self.index,
194	            total: self.total,
195	        });
196	
197	        // Blank line between steps
198	        if self.index > 0 {
199	            ui.message("");
200	        }
201	
202	        // ── Pre-engine: requirement gap resolution ──
203	        let mut unresolved_gaps: HashSet<String> = HashSet::new();
204	        if let Some(ref mut checker) = gap_checker {
205	            let provided = if opts.provided_requirements.is_empty() {
206	                None
207	            } else {
208	                Some(opts.provided_requirements)
209	            };
210	            let gaps = checker.check_step(self.step, provided);
211	            if !gaps.is_empty() {
212	                let installer_ctx = installer::default_context();
213	                let resolved =
214	                    installer::handle_gaps(&gaps, checker, ui, opts.interactive, &installer_ctx);
215	                match resolved {
216	                    Ok(true) => {}
217	                    Ok(false) | Err(_) => {
218	                        for gap in &gaps {
219	                            event_bus.emit(&BivvyEvent::RequirementGap {
220	                                name: self.step_name.to_string(),
221	                                requirement: gap.requirement.clone(),
222	                                status: format!("{:?}", gap.status),
223	                            });
224	                        }
225	                        unresolved_gaps.insert(self.step_name.to_string());
226	                    }
227	                }
228	            }
229	        }
230	
231	        let needs_force = opts.should_force(self.step_name) || self.step.behavior.force;
232	
233	        // ── Pre-engine: collect named check results for cross-step refs ──
234	        if !opts.dry_run {
235	            if let Some(check) = self.step.execution.effective_check() {
236	                if check.has_named_checks() {
237	                    let mut evaluator =
238	                        CheckEvaluator::new(opts.project_root, context, snapshot_store);
239	                    let step_named = satisfaction::collect_named_check_results(
240	                        self.step_name,
241	                        &check,
242	                        &mut evaluator,
243	                    );
244	                    named_check_results.extend(step_named);
245	                }
246	            }
247	        }
248	
249	        // ── Decision Engine ──
250	        let eval_result = if opts.dry_run {
251	            EvaluationResult {
252	                decision: StepDecision::AutoRun,
253	                reason: "dry run".to_string(),
254	                satisfaction: None,
255	            }
256	        } else {
257	            let mut engine_ctx = EngineContext {
258	                steps,
259	                project_root: opts.project_root,
260	                interpolation: context,
261	                snapshot_store,
262	                state,
263	                step_overrides,
264	                force: opts.force_steps,
265	                force_all: opts.force_all,
266	                named_check_results,
267	                satisfaction_cache,
268	                evaluated: HashMap::new(),
269	                failed_steps,
270	                user_skipped_steps,
271	                satisfied_steps,
272	                unresolved_gaps: &unresolved_gaps,
273	            };
274	            engine::evaluate_step(self.step_name, &mut engine_ctx)
275	        };
276	
277	        // Emit any baseline events from check evaluation
278	        emit_baseline_events(snapshot_store, event_bus);
279	
280	        // ── Act on the engine's decision ──
281	        match &eval_result.decision {
282	            StepDecision::Block { reason } => {
283	                return self.handle_block(
284	                    reason,
285	                    &step_header,
286	                    &step_pad,
287	                    failed_steps,
288	                    event_bus,
289	                    step_display,
290	                );
291	            }
292	
293	            StepDecision::Skip {
294	                reason: SkipReason::AutoSatisfied,
295	            } => {
296	                return self.handle_auto_satisfied(
297	                    &eval_result,
298	                    &step_header,
299	                    &step_pad,
300	                    needs_force,
301	                    event_bus,
302	                    step_display,
303	                );
304	            }
305	
306	            StepDecision::Prompt { prompt_key } => {
307	                step_display.message(&step_header);
308	
309	                if opts.interactive {
310	                    let outcome = self.handle_prompt(
311	                        prompt_key,
312	                        &eval_result,
313	                        &step_pad,
314	                        needs_force,
315	                        event_bus,
316	                        ui,
317	                        step_display,
318	                    )?;
319	                    if let Some(outcome) = outcome {
320	                        return Ok(outcome);
321	                    }
322	                    // None means fall through to execution
323	                }
324	                // Non-interactive: fall through to execution
325	            }
326	
327	            StepDecision::AutoRun | StepDecision::Run => {
328	                step_display.message(&step_header);
329	            }
330	
331	            StepDecision::Skip { reason } => {
332	                step_display.message(&step_header);
333	                step_display.message(&format!(
334	                    "{}{}",
335	                    step_pad,
336	                    StatusKind::Skipped.format(self.theme, reason.message())
337	                ));
338	                event_bus.emit(&BivvyEvent::StepSkipped {
339	                    name: self.step_name.to_string(),
340	                    reason: reason.message().to_string(),
341	                });
342	                event_bus.emit(&BivvyEvent::StepOutcome {
343	                    name: self.step_name.to_string(),
344	                    outcome: skip_reason_to_outcome(reason),
345	                    detail: Some(reason.message().to_string()),
346	                    duration_ms: None,
347	                });
348	                return Ok(StepAction::Skipped(
349	                    StepResult::skipped(&self.step.name, CheckResult::passed(reason.message())),
350	                    SkipCategory::Other,
351	                ));
352	            }
353	        }
354	
355	        // ── Step-level prompts (template inputs) ──
356	        if !self.step.output.prompts.is_empty() {
357	            for prompt_config in &self.step.output.prompts {
358	                if context.resolve(&prompt_config.key).is_some() {
359	                    continue;
360	                }
361	
362	                if !opts.interactive {
363	                    if let Some(default) = &prompt_config.default {
364	                        let default_str = match default {
365	                            serde_yaml::Value::String(s) => s.clone(),
366	                            serde_yaml::Value::Bool(b) => b.to_string(),
367	                            serde_yaml::Value::Number(n) => n.to_string(),
368	                            _ => format!("{:?}", default),
369	                        };
370	                        context
371	                            .prompts
372	                            .insert(prompt_config.key.clone(), default_str);
373	                    } else {
374	                        return Err(BivvyError::StepExecutionError {
375	                            step: self.step_name.to_string(),
376	                            message: format!(
377	                                "Prompt '{}' requires a value in non-interactive mode. \
378	                                 Set via env var, template input, or provide a default.",
379	                                prompt_config.key
380	                            ),
381	                        });
382	                    }
383	                    continue;
384	                }
385	
386	                let ui_prompt = config_prompt_to_ui_prompt(prompt_config);
387	                let result = ui.prompt(&ui_prompt)?;
388	                context
389	                    .prompts
390	                    .insert(prompt_config.key.clone(), result.as_string());
391	            }
392	        }
393	
394	        // ── Build step context and emit decision to run ──
395	        let step_ctx = StepContext {
396	            name: self.step_name,
397	            command: &self.step.execution.command,
398	            requires: &self.step.requires,
399	            template: None,
400	        };
401	
402	        event_bus.emit(&BivvyEvent::StepDecided {
403	            name: self.step_name.to_string(),
404	            decision: "run".to_string(),
405	            reason: None,
406	            trace: Some(DecisionTrace {
407	                behavior_flags: make_behavior_flags(self.step, needs_force),
408	                ..Default::default()
409	            }),
410	        });
411	        event_bus.emit(&BivvyEvent::StepStarting {
412	            name: self.step_name.to_string(),
413	        });
414	
415	        // ── Build workflow state for diagnostic funnel ──
416	        let workflow_state = {
417	            let step_refs: Vec<(&str, &ResolvedStep)> = steps
418	                .iter()
419	                .map(|(name, step)| (name.as_str(), step))
420	                .collect();
421	            let mut outcomes = HashMap::new();
422	            for r in results {
423	                outcomes.insert(r.name.clone(), r.status());
424	            }
425	            for s in satisfied_steps {
426	                outcomes.entry(s.clone()).or_insert(StepStatus::Completed);
427	            }
428	            for s in failed_steps {
429	                outcomes.entry(s.clone()).or_insert(StepStatus::Failed);
430	            }
431	            for s in user_skipped_steps {
432	                outcomes.entry(s.clone()).or_insert(StepStatus::Skipped);
433	            }
434	            (step_refs, outcomes)
435	        };
436	        let ws = diagnostic::WorkflowState {
437	            steps: &workflow_state.0,
438	            outcomes: &workflow_state.1,
439	        };
440	
441	        // ── Execute step with retry and recovery ──
442	        let step_number = self.step_number();
443	        let step_indent = self.step_indent();
444	        let exec_result = execute_step_with_recovery(
445	            self.step,
446	            self.step_name,
447	            &step_number,
448	            step_indent,
449	            opts.project_root,
450	            context,
451	            opts.base_env,
452	            opts.process_env,
453	            needs_force,
454	            opts.dry_run,
455	            opts.interactive,
456	            &step_ctx,
457	            opts.diagnostic_funnel,
458	            &ws,
459	            ui,
460	            step_display,
461	            event_bus,
462	        )?;
463	
464	        // ── Emit step completion event ──
465	        let duration_ms = exec_result.result.duration.as_millis() as u64;
466	        match exec_result.result.status() {
467	            StepStatus::Completed => {
468	                event_bus.emit(&BivvyEvent::StepCompleted {
469	                    name: self.step_name.to_string(),
470	                    success: true,
471	                    exit_code: exec_result.result.exit_code,
472	                    duration_ms,
473	                    error: None,
474	                });
475	                event_bus.emit(&BivvyEvent::StepOutcome {
476	                    name: self.step_name.to_string(),
477	                    outcome: StepOutcomeKind::Completed,
478	                    detail: None,
479	                    duration_ms: Some(duration_ms),
480	                });
481	            }
482	            StepStatus::Failed => {
483	                event_bus.emit(&BivvyEvent::StepCompleted {
484	                    name: self.step_name.to_string(),
485	                    success: false,
486	                    exit_code: exec_result.result.exit_code,
487	                    duration_ms,
488	                    error: exec_result.result.error.clone(),
489	                });
490	                event_bus.emit(&BivvyEvent::StepOutcome {
491	                    name: self.step_name.to_string(),
492	                    outcome: StepOutcomeKind::Failed,
493	                    detail: exec_result.result.error.clone(),
494	                    duration_ms: Some(duration_ms),
495	                });
496	            }
497	            StepStatus::Skipped => {
498	                let reason = exec_result
499	                    .result
500	                    .recovery_detail
501	                    .clone()
502	                    .unwrap_or_else(|| "skipped".to_string());
503	                event_bus.emit(&BivvyEvent::StepSkipped {
504	                    name: self.step_name.to_string(),
505	                    reason: reason.clone(),
506	                });
507	                // Reaching this branch means the step ran and the user chose
508	                // to skip during recovery — that's a `Declined` outcome.
509	                event_bus.emit(&BivvyEvent::StepOutcome {
510	                    name: self.step_name.to_string(),
511	                    outcome: StepOutcomeKind::Declined,
512	                    detail: Some(reason),
513	                    duration_ms: Some(duration_ms),
514	                });
515	            }
516	            _ => {}
517	        }
518	
519	        // ── Determine action ──
520	        if exec_result.aborted {
521	            return Ok(StepAction::Aborted(exec_result.result));
522	        }
523	
524	        let status = exec_result.result.status();
525	        Ok(match status {
526	            StepStatus::Completed => StepAction::Completed(exec_result.result),
527	            StepStatus::Failed => {
528	                if exec_result.skipped_by_user {
529	                    StepAction::Skipped(exec_result.result, SkipCategory::RecoverySkipped)
530	                } else {
531	                    StepAction::Failed(exec_result.result)
532	                }
533	            }
534	            StepStatus::Skipped => {
535	                StepAction::Skipped(exec_result.result, SkipCategory::RecoverySkipped)
536	            }
537	            _ => StepAction::Completed(exec_result.result),
538	        })
539	    }
540	
541	    /// Handle a blocked step (dependency failed, precondition failed, etc.).
542	    fn handle_block(
543	        &self,
544	        reason: &BlockReason,
545	        step_header_text: &str,
546	        step_pad: &str,
547	        _failed_steps: &HashSet<String>,
548	        event_bus: &mut EventBus,
549	        step_display: &mut dyn StepDisplay,
550	    ) -> Result<StepAction> {
551	        let reason_str = match reason {
552	            BlockReason::DependencyFailed { dependency } => {
553	                event_bus.emit(&BivvyEvent::DependencyBlocked {
554	                    name: self.step_name.to_string(),
555	                    blocked_by: dependency.clone(),
556	                    reason: "dependency_failed".to_string(),
557	                });
558	                "dependency_failed"
559	            }
560	            BlockReason::DependencySkipped { .. } => "dependency_skipped",
561	            BlockReason::PreconditionFailed { .. } => "precondition_failed",
562	            BlockReason::DependencyUnsatisfied { .. } => "dependency_unsatisfied",
563	        };
564	        event_bus.emit(&BivvyEvent::StepDecided {
565	            name: self.step_name.to_string(),
566	            decision: "block".to_string(),
567	            reason: Some(reason_str.to_string()),
568	            trace: None,
569	        });
570	        step_display.message(step_header_text);
571	        step_display.message(&format!(
572	            "{}{}",
573	            step_pad,
574	            StatusKind::Blocked.format(self.theme, &reason.message())
575	        ));
576	
577	        // Every block path — including DependencySkipped, which the workflow
578	        // treats as a transitive skip — emits StepOutcome::Blocked. The
579	        // detail string carries the user-facing reason ("Skipped (dependency
580	        // 'X' skipped)" vs "Blocked (precondition failed: ...)").
581	        event_bus.emit(&BivvyEvent::StepOutcome {
582	            name: self.step_name.to_string(),
583	            outcome: StepOutcomeKind::Blocked,
584	            detail: Some(reason.message()),
585	            duration_ms: None,
586	        });
587	
588	        // For dependency_skipped, return a skip result, not a block
589	        if matches!(reason, BlockReason::DependencySkipped { .. }) {
590	            Ok(StepAction::Skipped(
591	                StepResult::skipped(&self.step.name, CheckResult::passed("Dependency skipped")),
592	                SkipCategory::DependencySkipped,
593	            ))
594	        } else {
595	            Ok(StepAction::Blocked)
596	        }
597	    }
598	
599	    /// Handle an auto-satisfied step (check passed, no prompt needed).
600	    fn handle_auto_satisfied(
601	        &self,
602	        eval_result: &EvaluationResult,
603	        step_header_text: &str,
604	        step_pad: &str,
605	        needs_force: bool,
606	        event_bus: &mut EventBus,
607	        step_display: &mut dyn StepDisplay,
608	    ) -> Result<StepAction> {
609	        event_bus.emit(&BivvyEvent::StepDecided {
610	            name: self.step_name.to_string(),
611	            decision: "skip".to_string(),
612	            reason: Some("auto_satisfied".to_string()),
613	            trace: Some(DecisionTrace {
614	                behavior_flags: make_behavior_flags(self.step, needs_force),
615	                ..Default::default()
616	            }),
617	        });
618	        event_bus.emit(&BivvyEvent::StepSkipped {
619	            name: self.step_name.to_string(),
620	            reason: eval_result.reason.clone(),
621	        });
622	        event_bus.emit(&BivvyEvent::StepOutcome {
623	            name: self.step_name.to_string(),
624	            outcome: StepOutcomeKind::Satisfied,
625	            detail: Some(eval_result.reason.clone()),
626	            duration_ms: None,
627	        });
628	        step_display.message(step_header_text);
629	        let skip_label = crate::ui::satisfaction_label(&eval_result.reason);
630	        step_display.message(&format!(
631	            "{}{}",
632	            step_pad,
633	            StatusKind::Success.format(self.theme, &skip_label)
634	        ));
635	        Ok(StepAction::Skipped(
636	            StepResult::check_passed(
637	                &self.step.name,
638	                CheckResult::passed(eval_result.reason.clone()),
639	            ),
640	            SkipCategory::Satisfied,
641	        ))
642	    }
643	
644	    /// Handle a prompt decision. Returns `Some(StepAction)` if the step should
645	    /// not proceed to execution (user declined), or `None` to fall through.
646	    #[allow(clippy::too_many_arguments)]
647	    fn handle_prompt(
648	        &self,
649	        prompt_key: &str,
650	        eval_result: &EvaluationResult,
651	        step_pad: &str,
652	        _needs_force: bool,
653	        event_bus: &mut EventBus,
654	        ui: &mut dyn UserInterface,
655	        step_display: &mut dyn StepDisplay,
656	    ) -> Result<Option<StepAction>> {
657	        if prompt_key.starts_with("rerun_") {
658	            let prompt_text = format!("{}. Run again?", eval_result.reason);
659	            let prompt = Prompt {
660	                key: prompt_key.to_string(),
661	                question: format!("{}{}", step_pad, prompt_text),
662	                prompt_type: PromptType::Select {
663	                    options: vec![
664	                        PromptOption {
665	                            label: "No  (n)".to_string(),
666	                            value: "no".to_string(),
667	                        },
668	                        PromptOption {
669	                            label: "Yes (y)".to_string(),
670	                            value: "yes".to_string(),
671	                        },
672	                    ],
673	                },
674	                default: Some("no".to_string()),
675	            };
676	            let answer = ui.prompt(&prompt)?;
677	            // clear_lines removed — surface tracks regions
678	            if answer.as_string() != "yes" {
679	                event_bus.emit(&BivvyEvent::StepSkipped {
680	                    name: self.step_name.to_string(),
681	                    reason: eval_result.reason.clone(),
682	                });
683	                event_bus.emit(&BivvyEvent::StepOutcome {
684	                    name: self.step_name.to_string(),
685	                    outcome: StepOutcomeKind::Satisfied,
686	                    detail: Some(eval_result.reason.clone()),
687	                    duration_ms: None,
688	                });
689	                let skip_label = crate::ui::satisfaction_label(&eval_result.reason);
690	                step_display.message(&format!(
691	                    "{}{}",
692	                    step_pad,
693	                    StatusKind::Success.format(self.theme, &skip_label)
694	                ));
695	                return Ok(Some(StepAction::Skipped(
696	                    StepResult::check_passed(
697	                        &self.step.name,
698	                        CheckResult::passed(eval_result.reason.clone()),
699	                    ),
700	                    SkipCategory::Satisfied,
701	                )));
702	            }
703	            // User chose yes — fall through to execution
704	        } else if prompt_key.starts_with("autorun_") {
705	            let prompt_text = format!("Run {}?", self.step.title);
706	            let prompt = Prompt {
707	                key: prompt_key.to_string(),
708	                question: format!("{}{}", step_pad, prompt_text),
709	                prompt_type: PromptType::Select {
710	                    options: vec![
711	                        PromptOption {
712	                            label: "Yes (y)".to_string(),
713	                            value: "yes".to_string(),
714	                        },
715	                        PromptOption {
716	                            label: "No  (n)".to_string(),
717	                            value: "no".to_string(),
718	                        },
719	                    ],
720	                },
721	                default: Some("yes".to_string()),
722	            };
723	            event_bus.emit(&BivvyEvent::UserPrompted {
724	                step: Some(self.step_name.to_string()),
725	                prompt: prompt_text,
726	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
727	            });
728	            let answer = ui.prompt(&prompt)?;
729	            let answer_str = answer.as_string();
730	            event_bus.emit(&BivvyEvent::UserResponded {
731	                step: Some(self.step_name.to_string()),
732	                input: answer_str.clone(),
733	                method: crate::logging::InputMethod::ArrowSelect,
734	            });
735	            if answer_str != "yes" {
736	                // clear_lines removed — surface tracks regions
737	                event_bus.emit(&BivvyEvent::StepDecided {
738	                    name: self.step_name.to_string(),
739	                    decision: "skip".to_string(),
740	                    reason: Some("user_declined_auto_run".to_string()),
741	                    trace: None,
742	                });
743	                event_bus.emit(&BivvyEvent::StepSkipped {
744	                    name: self.step_name.to_string(),
745	                    reason: "user_declined_auto_run".to_string(),
746	                });
747	                event_bus.emit(&BivvyEvent::StepOutcome {
748	                    name: self.step_name.to_string(),
749	                    outcome: StepOutcomeKind::Declined,
750	                    detail: Some("user_declined_auto_run".to_string()),
751	                    duration_ms: None,
752	                });
753	                step_display.message(&format!(
754	                    "{}{}",
755	                    step_pad,
756	                    self.theme.format_skipped("Skipped")
757	                ));
758	                return Ok(Some(StepAction::Skipped(
759	                    StepResult::skipped(
760	                        &self.step.name,
761	                        CheckResult::passed("User declined to run"),
762	                    ),
763	                    SkipCategory::UserDeclined,
764	                )));
765	            }
766	            // clear_lines removed — surface tracks regions
767	        } else if prompt_key.starts_with("confirm_") {
768	            let prompt_text = format!("{}?", self.step.title);
769	            let prompt = Prompt {
770	                key: prompt_key.to_string(),
771	                question: format!("{}{}", step_pad, prompt_text),
772	                prompt_type: PromptType::Select {
773	                    options: vec![
774	                        PromptOption {
775	                            label: "Yes (y)".to_string(),
776	                            value: "yes".to_string(),
777	                        },
778	                        PromptOption {
779	                            label: "No  (n)".to_string(),
780	                            value: "no".to_string(),
781	                        },
782	                    ],
783	                },
784	                default: Some("yes".to_string()),
785	            };
786	            event_bus.emit(&BivvyEvent::UserPrompted {
787	                step: Some(self.step_name.to_string()),
788	                prompt: prompt_text,
789	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
790	            });
791	            let answer = ui.prompt(&prompt)?;
792	            let answer_str = answer.as_string();
793	            event_bus.emit(&BivvyEvent::UserResponded {
794	                step: Some(self.step_name.to_string()),
795	                input: answer_str.clone(),
796	                method: crate::logging::InputMethod::ArrowSelect,
797	            });
798	            if answer_str != "yes" {
799	                // clear_lines removed — surface tracks regions
800	                event_bus.emit(&BivvyEvent::StepDecided {
801	                    name: self.step_name.to_string(),
802	                    decision: "skip".to_string(),
803	                    reason: Some("user_declined".to_string()),
804	                    trace: None,
805	                });
806	                event_bus.emit(&BivvyEvent::StepSkipped {
807	                    name: self.step_name.to_string(),
808	                    reason: "user_declined".to_string(),
809	                });
810	                event_bus.emit(&BivvyEvent::StepOutcome {
811	                    name: self.step_name.to_string(),
812	                    outcome: StepOutcomeKind::Declined,
813	                    detail: Some("user_declined".to_string()),
814	                    duration_ms: None,
815	                });
816	                step_display.message(&format!(
817	                    "{}{}",
818	                    step_pad,
819	                    self.theme.format_skipped("Skipped")
820	                ));
821	                return Ok(Some(StepAction::Skipped(
822	                    StepResult::skipped(&self.step.name, CheckResult::passed("User declined")),
823	                    SkipCategory::UserDeclined,
824	                )));
825	            }
826	            // clear_lines removed — surface tracks regions
827	        } else if prompt_key.starts_with("sensitive_") {
828	            let prompt_text = "Handles sensitive data. Continue?";
829	            let prompt = Prompt {
830	                key: prompt_key.to_string(),
831	                question: prompt_text.to_string(),
832	                prompt_type: PromptType::Select {
833	                    options: vec![
834	                        PromptOption {
835	                            label: "Yes (y)".to_string(),
836	                            value: "yes".to_string(),
837	                        },
838	                        PromptOption {
839	                            label: "No (n)".to_string(),
840	                            value: "no".to_string(),
841	                        },
842	                    ],
843	                },
844	                default: Some("yes".to_string()),
845	            };
846	            event_bus.emit(&BivvyEvent::UserPrompted {
847	                step: Some(self.step_name.to_string()),
848	                prompt: prompt_text.to_string(),
849	                options: vec!["Yes (y)".to_string(), "No (n)".to_string()],
850	            });
851	            let answer = ui.prompt(&prompt)?;
852	            let answer_str = answer.as_string();
853	            event_bus.emit(&BivvyEvent::UserResponded {
854	                step: Some(self.step_name.to_string()),
855	                input: answer_str.clone(),
856	                method: crate::logging::InputMethod::ArrowSelect,
857	            });
858	            if answer_str != "yes" {
859	                if self.step.behavior.skippable {
860	                    event_bus.emit(&BivvyEvent::StepSkipped {
861	                        name: self.step_name.to_string(),
862	                        reason: "user_declined_sensitive".to_string(),
863	                    });
864	                    event_bus.emit(&BivvyEvent::StepOutcome {
865	                        name: self.step_name.to_string(),
866	                        outcome: StepOutcomeKind::Declined,
867	                        detail: Some("user_declined_sensitive".to_string()),
868	                        duration_ms: None,
869	                    });
870	                    step_display.message(&format!(
871	                        "{}{}",
872	                        step_pad,
873	                        self.theme
874	                            .format_skipped("Skipped (declined sensitive step)")
875	                    ));
876	                    return Ok(Some(StepAction::Skipped(
877	                        StepResult::skipped(
878	                            &self.step.name,
879	                            CheckResult::passed("User declined sensitive step"),
880	                        ),
881	                        SkipCategory::UserDeclined,
882	                    )));
883	                } else {
884	                    return Err(BivvyError::StepExecutionError {
885	                        step: self.step_name.to_string(),
886	                        message: format!(
887	                            "Step '{}' is sensitive and not skippable, but user declined",
888	                            self.step.title
889	                        ),
890	                    });
891	                }
892	            }
893	            // User chose yes — fall through to execution
894	        }
895	
896	        Ok(None) // Fall through to execution
897	    }
898	}
899	
900	/// Map a [`SkipReason`] (produced by the decision engine) to the typed
901	/// terminal [`StepOutcomeKind`] it represents.
902	///
903	/// `SkipReason::AutoSatisfied` is handled by `handle_auto_satisfied` and
904	/// never reaches the generic skip fall-through, but we map it here for
905	/// completeness so a future caller cannot misroute it.
906	fn skip_reason_to_outcome(reason: &SkipReason) -> StepOutcomeKind {
907	    match reason {
908	        SkipReason::CheckPassed | SkipReason::Satisfied | SkipReason::AutoSatisfied => {
909	            StepOutcomeKind::Satisfied
910	        }
911	        SkipReason::UserDeclined | SkipReason::SensitiveDeclined => StepOutcomeKind::Declined,
912	        SkipReason::RequirementNotMet => StepOutcomeKind::Blocked,
913	    }
914	}
915	
916	/// Drain pending baseline events from the snapshot store and emit them on the event bus.
917	fn emit_baseline_events(snapshot_store: &mut SnapshotStore, event_bus: &mut EventBus) {
918	    for evt in snapshot_store.drain_events() {
919	        match evt.change {
920	            crate::snapshots::BaselineChange::Established => {
921	                event_bus.emit(&BivvyEvent::BaselineEstablished {
922	                    step: evt.step,
923	                    target: evt.target,
924	                    hash: evt.hash,
925	                    scope: evt.scope,
926	                });
927	            }
928	            crate::snapshots::BaselineChange::Updated { old_hash } => {
929	                event_bus.emit(&BivvyEvent::BaselineUpdated {
930	                    step: evt.step,
931	                    target: evt.target,
932	                    old_hash,
933	                    new_hash: evt.hash,
934	                });
935	            }
936	            crate::snapshots::BaselineChange::Unchanged => {}
937	        }
938	    }
939	}
940	
941	/// Build behavior flags from a resolved step and force status.
942	fn make_behavior_flags(step: &ResolvedStep, forced: bool) -> BehaviorFlags {
943	    BehaviorFlags {
944	        skippable: step.behavior.skippable,
945	        required: step.behavior.required,
946	        forced,
947	        auto_run: step.behavior.auto_run,
948	        prompt_on_rerun: step.behavior.prompt_on_rerun,
949	        confirm: step.behavior.confirm,
950	    }
951	}
