//! Trait for building prompts, decoupling runner logic from UI presentation.
//!
//! The runner expresses *intent* ("I need a recovery choice for step X")
//! and the factory produces the appropriate [`Prompt`] with labels, options,
//! and defaults. This allows different UI contexts (terminal, CI, tests)
//! to produce different prompt structures without changing business logic.

use super::{Prompt, PromptOption, PromptType};

/// Describes a fix option available in the recovery menu.
#[derive(Debug, Clone)]
pub struct RecoveryFixOption {
    pub label: String,
    pub value: String,
}

/// Trait for building UI prompts from business-level parameters.
///
/// Implementors decide the question text, option labels, prompt type, and
/// defaults. The runner never constructs [`Prompt`] structs directly.
pub trait PromptFactory {
    /// Build a recovery menu prompt for a failed step.
    ///
    /// `fix_options` contains labeled fix/suggestion actions already filtered
    /// by confidence and history. `has_custom_fix` controls whether a
    /// "Fix (custom)" option is offered.
    fn recovery_menu(
        &self,
        step_name: &str,
        fix_options: &[RecoveryFixOption],
        has_custom_fix: bool,
    ) -> Prompt;

    /// Build a text input prompt for entering a custom fix command.
    fn custom_fix_input(&self, step_name: &str) -> Prompt;

    /// Build a confirmation prompt for running a specific fix command.
    fn confirm_fix(&self, step_name: &str, command: &str) -> Prompt;

    /// Build a "run again?" prompt for an already-satisfied step.
    fn rerun_prompt(&self, key: &str, reason: &str, indent: &str) -> Prompt;

    /// Build a "run this step?" prompt for auto-run steps.
    fn autorun_prompt(&self, key: &str, title: &str, indent: &str) -> Prompt;

    /// Build a confirmation prompt for a step requiring explicit consent.
    fn confirm_prompt(&self, key: &str, title: &str, indent: &str) -> Prompt;

    /// Build a prompt for steps handling sensitive data.
    fn sensitive_prompt(&self, key: &str) -> Prompt;

    /// Build a telemetry consent prompt.
    fn telemetry_consent(&self) -> Prompt;
}

/// Default prompt factory producing the standard terminal prompts.
#[derive(Debug, Clone, Default)]
pub struct DefaultPromptFactory;

impl PromptFactory for DefaultPromptFactory {
    fn recovery_menu(
        &self,
        step_name: &str,
        fix_options: &[RecoveryFixOption],
        has_custom_fix: bool,
    ) -> Prompt {
        let mut options = vec![PromptOption {
            label: "Retry".to_string(),
            value: "retry".to_string(),
        }];

        for fix in fix_options {
            options.push(PromptOption {
                label: fix.label.clone(),
                value: fix.value.clone(),
            });
        }

        if has_custom_fix {
            options.push(PromptOption {
                label: "Fix (custom) — enter your own command".to_string(),
                value: "custom_fix".to_string(),
            });
        }

        options.push(PromptOption {
            label: "Skip".to_string(),
            value: "skip".to_string(),
        });
        options.push(PromptOption {
            label: "Shell".to_string(),
            value: "shell".to_string(),
        });
        options.push(PromptOption {
            label: "Abort".to_string(),
            value: "abort".to_string(),
        });

        Prompt {
            key: format!("recovery_{}", step_name),
            question: "How do you want to proceed?".to_string(),
            prompt_type: PromptType::Select { options },
            default: Some("retry".to_string()),
        }
    }

    fn custom_fix_input(&self, step_name: &str) -> Prompt {
        Prompt {
            key: format!("custom_fix_{}", step_name),
            question: "Enter fix command:".to_string(),
            prompt_type: PromptType::Input,
            default: None,
        }
    }

    fn confirm_fix(&self, step_name: &str, command: &str) -> Prompt {
        Prompt {
            key: format!("confirm_fix_{}", step_name),
            question: format!("Run `{}`?", command),
            prompt_type: PromptType::Confirm,
            default: Some("yes".to_string()),
        }
    }

    fn rerun_prompt(&self, key: &str, reason: &str, indent: &str) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: format!("{}{}. Run again?", indent, reason),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "No  (n)".to_string(),
                        value: "no".to_string(),
                    },
                    PromptOption {
                        label: "Yes (y)".to_string(),
                        value: "yes".to_string(),
                    },
                ],
            },
            default: Some("no".to_string()),
        }
    }

    fn autorun_prompt(&self, key: &str, title: &str, indent: &str) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: format!("{}Run {}?", indent, title),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "Yes (y)".to_string(),
                        value: "yes".to_string(),
                    },
                    PromptOption {
                        label: "No  (n)".to_string(),
                        value: "no".to_string(),
                    },
                ],
            },
            default: Some("yes".to_string()),
        }
    }

    fn confirm_prompt(&self, key: &str, title: &str, indent: &str) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: format!("{}{}?", indent, title),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "Yes (y)".to_string(),
                        value: "yes".to_string(),
                    },
                    PromptOption {
                        label: "No  (n)".to_string(),
                        value: "no".to_string(),
                    },
                ],
            },
            default: Some("yes".to_string()),
        }
    }

    fn sensitive_prompt(&self, key: &str) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: "Handles sensitive data. Continue?".to_string(),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "Yes (y)".to_string(),
                        value: "yes".to_string(),
                    },
                    PromptOption {
                        label: "No (n)".to_string(),
                        value: "no".to_string(),
                    },
                ],
            },
            default: Some("yes".to_string()),
        }
    }

    fn telemetry_consent(&self) -> Prompt {
        Prompt {
            key: "telemetry_failure".to_string(),
            question: "Save this failure report?".to_string(),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "Send".to_string(),
                        value: "send".to_string(),
                    },
                    PromptOption {
                        label: "No thanks".to_string(),
                        value: "no_thanks".to_string(),
                    },
                    PromptOption {
                        label: "Always send".to_string(),
                        value: "always".to_string(),
                    },
                    PromptOption {
                        label: "Never ask".to_string(),
                        value: "never".to_string(),
                    },
                ],
            },
            default: Some("no_thanks".to_string()),
        }
    }
}

