        ResolutionCandidate {
            label: label.to_string(),
            command: Some(command.to_string()),
            explanation: format!("Explanation for {}", label),
            confidence,
            source: crate::runner::diagnostic::ResolutionSource::Deduced,
            platform: None,
        }
    }

    #[test]
    fn prompt_recovery_multi_default_is_retry() {
